INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3807721, 536374, 77838, '<td valign="top">Some kind of pasta? Maybe ravioli or bow-tie; is that celery in the middle? lol, I''m probably so far off! I like it though, it''s weird looking.</td>', 'Some kind of pasta? Maybe ravioli or bow-tie; is that celery in the middle? lol, I''m probably so far off! I like it though, it''s weird looking.', '2007-06-20 12:29:55.000000', NULL, 1),
(3807749, 536462, 56243, '<td valign="top">It is entirely too bright on the right side and really fuzzy.</td>', 'It is entirely too bright on the right side and really fuzzy.', '2007-06-20 12:34:45.000000', NULL, 1),
(3807750, 538089, 9162, '<td valign="top">I''m stumped.  I have no idea what I''m looking at but it is beautiful.  Love the colors and texture.  10</td>', 'I''m stumped.  I have no idea what I''m looking at but it is beautiful.  Love the colors and texture.  10', '2007-06-20 12:34:50.000000', NULL, 1),
(3807765, 539008, 77838, '<td valign="top">Looks like eggcases from baby sharks?</td>', 'Looks like eggcases from baby sharks?', '2007-06-20 12:36:14.000000', NULL, 1),
(3807775, 539121, 56243, '<td valign="top">I would say a fur coat.  At first i was guessing hair, simply hair because of the red hair on the far left I changed it to a fur coat or stole.  However, photo wise the picture is a bit flat.  Maybe some more contrast is needed or better lighting because it''s also a bit dark.</td>', 'I would say a fur coat.  At first i was guessing hair, simply hair because of the red hair on the far left I changed it to a fur coat or stole.  However, photo wise the picture is a bit flat.  Maybe some more contrast is needed or better lighting because it''s also a bit dark.', '2007-06-20 12:38:04.000000', NULL, 1),
(3807784, 538573, 56243, '<td valign="top">How is this even fit the challenge of a Macro PUZZLE?</td>', 'How is this even fit the challenge of a Macro PUZZLE?', '2007-06-20 12:40:25.000000', NULL, 1),
(3807785, 539425, 61958, '<td valign="top">Cantalope?</td>', 'Cantalope?', '2007-06-20 12:40:27.000000', NULL, 1),
