(3807799, 539998, 61958, '<td valign="top">Cut Wire?</td>', 'Cut Wire?', '2007-06-20 12:42:42.000000', NULL, 1),
(3807802, 535902, 56243, '<td valign="top">Giant Rubber Band Ball!!!!!  Honestly nice colors used however it''s a bit dark and flat.  Plus the white bands have a pink hue to them.</td>', 'Giant Rubber Band Ball!!!!!  Honestly nice colors used however it''s a bit dark and flat.  Plus the white bands have a pink hue to them.', '2007-06-20 12:43:10.000000', NULL, 1),
(3807810, 538573, 61958, '<td valign="top">not sure how this is macro??? nor is it a puzzle sicne you''ve told us what it is</td>', 'not sure how this is macro??? nor is it a puzzle sicne you''ve told us what it is', '2007-06-20 12:44:06.000000', NULL, 1),
(3807842, 535201, 43774, '<td valign="top">Cool! Looks like spun glass but it''s probably plastic fibes of some sort. Could use just a tad more dof maybe?</td>', 'Cool! Looks like spun glass but it''s probably plastic fibes of some sort. Could use just a tad more dof maybe?', '2007-06-20 12:48:23.000000', NULL, 1),
(3807845, 539870, 56243, '<td valign="top">I was guessing pencil shavings that were desaturated but it''s reflecting the blue off the material so I''m guessing metal shavings from a drill while trying drill a hole.  Very good photo quality.</td>', 'I was guessing pencil shavings that were desaturated but it''s reflecting the blue off the material so I''m guessing metal shavings from a drill while trying drill a hole.  Very good photo quality.', '2007-06-20 12:49:19.000000', NULL, 1),
(3807855, 538904, 56243, '<td valign="top">nice idea , but would be better if the whole word love is in full focus instead of the letters ve and a few above and below it.</td>', 'nice idea , but would be better if the whole word love is in full focus instead of the letters ve and a few above and below it.', '2007-06-20 12:50:23.000000', NULL, 1),
