INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3844999, 536345, 34659, '<td valign="top">This is stunning Doc!  Beautiful flowing lines and tones, with just the right amount of detail and blur.  Well done!</td>', 'This is stunning Doc!  Beautiful flowing lines and tones, with just the right amount of detail and blur.  Well done!', '2007-06-28 11:23:01.000000', NULL, 0),
(3845000, 538709, 34659, '<td valign="top">Cool idea &amp; shot!  Congrats on top 10.</td>', 'Cool idea & shot!  Congrats on top 10.', '2007-06-28 11:23:27.000000', NULL, 0),
(3845002, 539610, 34659, '<td valign="top">This is so creative!  Well done - I really like the tones.</td>', 'This is so creative!  Well done - I really like the tones.', '2007-06-28 11:24:03.000000', NULL, 0),
(3845017, 538089, 24454, '<td valign="top">Jimmy!  What a beautiful abstract!  Mega Congratulations on an honorable mention!<br/> <br/></td>', 'Jimmy!  What a beautiful abstract!  Mega Congratulations on an honorable mention! ', '2007-06-28 11:29:32.000000', NULL, 0),
(3845019, 537091, 78255, '<td valign="top">I am the only one who voted this a 10?!? Harrumph! I actually think it is cool that the image is of something not particularly appealing. You made it look good. Nice work.</td>', 'I am the only one who voted this a 10?!? Harrumph! I actually think it is cool that the image is of something not particularly appealing. You made it look good. Nice work.', '2007-06-28 11:29:43.000000', NULL, 0),
(3845021, 537388, 24454, '<td valign="top">Catherine, this is fabulous!  Congratulations on having such an amazing photo -- and a front page finish :)<br/></td>', 'Catherine, this is fabulous!  Congratulations on having such an amazing photo -- and a front page finish :)', '2007-06-28 11:30:36.000000', NULL, 0),
(3845025, 539228, 78255, '<td valign="top">Ok, so my love of dolphins and dolphin sculptures may have weighed in on my #10 vote. But jeez I thought this would do better.</td>', 'Ok, so my love of dolphins and dolphin sculptures may have weighed in on my #10 vote. But jeez I thought this would do better.', '2007-06-28 11:31:21.000000', NULL, 0),
